import React, { useState } from 'react';
import { BookOpen, CheckCircle, AlertCircle, Sparkles, RefreshCw, HelpCircle } from 'lucide-react';
import { checkGrammar } from '../services/api';

const GrammarTool = ({ languages, selectedLang, username }) => {
  const [targetLang, setTargetLang] = useState(selectedLang || 'es');
  const [inputText, setInputText] = useState('');
  const [analysisResult, setAnalysisResult] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleAnalyze = async () => {
    if (!inputText.trim()) return;
    setIsLoading(true);
    try {
      const res = await checkGrammar(inputText, targetLang, username);
      setAnalysisResult(res.analysis_and_correction);
    } catch (e) {
      console.error("Grammar check error:", e);
      setAnalysisResult("Grammar analysis error. Please ensure backend is connected.");
    } finally {
      setIsLoading(false);
    }
  };

  const sampleSentences = [
    "Yo ir a la tienda ayer.",
    "She do not like cold weather.",
    "Je suis aller au cinéma demain."
  ];

  const langMeta = languages[targetLang] || { name: targetLang, flag: '🌐' };

  return (
    <div className="glass-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column', padding: '24px', gap: '20px', overflowY: 'auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderBottom: '1px solid rgba(255, 255, 255, 0.1)', paddingBottom: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ background: 'linear-gradient(135deg, #3b82f6, #8b5cf6)', padding: '10px', borderRadius: '12px' }}>
            <BookOpen size={20} color="#fff" />
          </div>
          <div>
            <h2 style={{ fontSize: '18px', fontWeight: 700, color: '#fff' }}>Grammar & Tutoring Studio</h2>
            <p style={{ fontSize: '12px', color: '#9ca3af' }}>Analyze sentence structure, verb conjugations, and rule explanations</p>
          </div>
        </div>

        {/* Target Language Selector */}
        <select 
          value={targetLang}
          onChange={(e) => setTargetLang(e.target.value)}
          style={{
            background: 'rgba(30, 41, 59, 0.9)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '10px',
            padding: '8px 14px',
            color: '#fff',
            fontSize: '13px',
            outline: 'none',
            cursor: 'pointer'
          }}
        >
          {Object.entries(languages || {}).map(([code, meta]) => (
            <option key={code} value={code}>
              {meta.flag} {meta.name} ({meta.native})
            </option>
          ))}
        </select>
      </div>

      {/* Input Area */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <label style={{ fontSize: '13px', color: '#9ca3af', fontWeight: 500 }}>
          Enter a sentence in {langMeta.name} to evaluate:
        </label>
        <textarea 
          placeholder={`Type a sentence in ${langMeta.name} (e.g. check spelling, word order, or verb tenses)...`}
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          style={{
            minHeight: '120px',
            background: 'rgba(15, 23, 42, 0.8)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '12px',
            padding: '14px',
            color: '#fff',
            fontSize: '14px',
            lineHeight: '1.6',
            resize: 'none',
            outline: 'none'
          }}
        />

        <button 
          onClick={handleAnalyze} 
          disabled={isLoading || !inputText.trim()}
          className="glow-btn"
          style={{ padding: '12px' }}
        >
          {isLoading ? <RefreshCw size={16} className="animate-spin" /> : <Sparkles size={16} />}
          <span>{isLoading ? 'Analyzing Grammar...' : 'Analyze Grammar & Spelling'}</span>
        </button>
      </div>

      {/* Analysis Output Result Card */}
      {analysisResult && (
        <div 
          style={{
            background: 'linear-gradient(135deg, rgba(30, 41, 59, 0.9), rgba(15, 23, 42, 0.9))',
            border: '1px solid rgba(139, 92, 246, 0.3)',
            borderRadius: '14px',
            padding: '20px',
            display: 'flex',
            flexDirection: 'column',
            gap: '12px'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#c084fc', fontSize: '14px', fontWeight: 600 }}>
            <CheckCircle size={18} color="#10b981" />
            <span>AI Tutoring Breakdown:</span>
          </div>

          <div style={{ color: '#fff', fontSize: '14px', lineHeight: '1.7', whiteSpace: 'pre-wrap', userSelect: 'text' }}>
            {analysisResult}
          </div>
        </div>
      )}

      {/* Preset Practice Sentences */}
      <div style={{ borderTop: '1px solid rgba(255, 255, 255, 0.1)', paddingTop: '14px' }}>
        <div style={{ fontSize: '12px', color: '#9ca3af', marginBottom: '8px' }}>Test sample practice sentences with intentional errors:</div>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {sampleSentences.map((sentence, i) => (
            <button 
              key={i}
              onClick={() => setInputText(sentence)}
              className="icon-action-btn"
              style={{ fontSize: '12px' }}
            >
              "{sentence}"
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default GrammarTool;
